  "name_zh": "裂空突刺",
  "concept": "將累積的動能凝聚於刃尖，以一次貫穿敵人的重擊換取短暫的失明與連擊進度。",
  "cast_flavor": "身影在空氣中拉出殘影，劍鋒帶著低沉的破空聲直插而出，敵人在白光中迷失了方向。"
}

{
  "pick": 0,
  "name_zh": "裂空突刺",
  "concept": "將動能凝聚於刃尖，對敵方造成武器傷害並施加致盲，同時為自己累積連擊點。",
  "cast_flavor": "劍鋒劃破空氣發出低沉的鳴響，白光在敵眼間炸開，其身影在眩目中暫時喪失了方向感。"
}

{
  "pick": 0,
  "name_zh": "聖光終結",
  "concept": "將積蓄的怒意轉化為貫穿敵人的神聖光芒，使其徹底倒下。",
  "cast_flavor": "掌心匯聚純白輝芒，沿直線猛然射出，將目標重重壓倒在地。"
}

{
  "pick": 1,
  "name_zh": "淨靈顯影",
  "concept": "以神聖之力照破隱蔽，讓隱藏的敵意與陷阱暴露無遺。",
  "cast_flavor": "法器散發出柔和而堅毅的光暈，水紋在光中擴散，將幽暗中的身影一一勾繪出來。"
}

{
  "pick": 1,
  "name_zh": "聖泉昭示",
  "concept": "神聖之水漫過戰場，將潛伏的敵意與陷阱一一顯現。",
  "cast_flavor": "法器輕顫，清澈的水流劃出十字軌跡，浸潤過的格子泛起微光，讓躲藏的敵人無處遁形。"
}

{
  "pick": 0,
  "name_zh": "寒鏈鎖影",
  "concept": "冰霜凝成無形之鏈，將敵人拽至身側並造成凍傷。",
  "cast_flavor": "指尖劃出凌冽光軌，遠處的敵人身軀被驟然拉近，撞擊聲中結晶蔓延。"
}

{
  "pick": 0,
  "name_zh": "灼地紋章",
